import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Using codemods","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/codemod/docs/using-codemods.md"},"headers":[],"relativePath":"tools/codemod/docs/using-codemods.md","filePath":"tools/codemod/docs/using-codemods.md","lastUpdated":1792005893000}`),a={name:`tools/codemod/docs/using-codemods.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="using-codemods" tabindex="-1">Using codemods <a class="header-anchor" href="#using-codemods" aria-label="Permalink to “Using codemods”">​</a></h1><p><code>@pumpkin-plugins/codemod</code> provides named, repeatable migrations for Pumpkin plugin projects. The CLI previews changes by default. It writes files only when you pass <code>--write</code>. The package requires Node.js <code>24.21.0</code> or newer.</p><h2 id="run-a-migration" tabindex="-1">Run a migration <a class="header-anchor" href="#run-a-migration" aria-label="Permalink to “Run a migration”">​</a></h2><p>After the first public npm release, list the available migrations from your plugin directory:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/codemod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>Install the plugin&#39;s dependencies before updating its builder version. From the plugin root, preview the latest published builder update and its release-specific migrations:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/codemod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The command resolves the builder version installed in that project and fetches npm&#39;s current <code>latest</code> version without using a cached result. It applies only migrations introduced after the installed version and no later than the target release, in release order. Preview is the default; apply the result with <code>--write</code>:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/codemod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --write</span></span></code></pre></div><p>Supported exact, caret and tilde builder ranges keep their range style. Catalog, workspace, npm alias, URL, file, git and composite ranges remain unchanged with a manual update note. The codemod does not add a direct builder dependency when one is absent. Review the preview and run your package manager after applying changes to refresh the lockfile.</p><p>Preview the Pumpkin API migration:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/codemod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate-pumpkin-api-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The command reports changed files and review notes without writing. To apply the same changes:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/codemod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate-pumpkin-api-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --write</span></span></code></pre></div><p>Write mode replaces each file atomically. A run that fails partway is not a multi-file transaction; the error names files already updated so you can review them before rerunning.</p><p>You can pass one or more files or directories instead of <code>.</code>. The CLI searches directories recursively, skipping child directories named <code>.git</code>, <code>.cache</code>, <code>.turbo</code>, <code>build</code>, <code>coverage</code>, <code>dist</code>, or <code>node_modules</code>. An explicitly supplied directory is scanned even if its name is on that list. Only regular files are scanned; symlinked files and directories are ignored. Start in the plugin directory you intend to migrate when working in a monorepo. For a complete migration, scan the plugin root: narrower inputs intentionally skip project files outside those paths and can leave the migration incomplete.</p><p>Use <code>--print</code> to print the full transformed contents of each changed file. It does not write by itself; combine it with <code>--write</code> only when you also want the files changed on disk.</p><h2 id="what-the-pumpkin-api-migration-changes" tabindex="-1">What the Pumpkin API migration changes <a class="header-anchor" href="#what-the-pumpkin-api-migration-changes" aria-label="Permalink to “What the Pumpkin API migration changes”">​</a></h2><p>The <code>migrate-pumpkin-api-ts</code> codemod follows the repository&#39;s <a href="./../../pumpkin-api/docs/migration">API migration guide</a>. It updates:</p><ul><li>JavaScript and TypeScript imports, exports, import types, dynamic imports and <code>require()</code> calls from <code>@pumpkinmc/pumpkin-api-ts</code> to <code>@pumpkin-plugins/pumpkin-api</code>.</li><li><code>package.json</code> dependencies, replacing the old API package with <code>@pumpkin-plugins/pumpkin-api</code> and adding <code>@pumpkin-plugins/build</code> under <code>dependencies</code>. The old package is removed from <code>dependencies</code>, <code>devDependencies</code>, <code>peerDependencies</code>, or <code>optionalDependencies</code> wherever it is declared; each existing version range for the replacement packages is retained and moved into <code>dependencies</code>. For either package without an existing range, the codemod adds it at <code>^0.1.0</code>.</li><li>A recognized <code>pumpkin-plugin-build &lt;entry&gt; &lt;output&gt;</code> command to <code>pumpkin-plugins-build</code>, moving the two paths into <code>pumpkinPlugin.entry</code> and <code>pumpkinPlugin.output</code>.</li><li>Missing <code>pumpkinPlugin.engine</code> and <code>pumpkinPlugin.wasi</code> settings to <code>quickjs</code> and <code>[]</code> when it can infer the builder paths or update an object-valued <code>pumpkinPlugin</code> config. This keeps the runtime engine stable and initializes the capabilities list for manual review; existing values are kept.</li><li><code>scripts.typecheck</code> as <code>pumpkin-plugins-build --types-only &amp;&amp; tsc --noEmit</code> when the codemod has both builder paths and the field is missing or exactly <code>tsc --noEmit</code>.</li><li><code>build/types/bindings/**/*.d.ts</code> in an explicit <code>tsconfig.json</code> <code>include</code> array. If the project inherits a restrictive include, it copies the effective patterns into the local config before adding the generated declarations. If there is no effective include but a local or inherited <code>files</code> list, it adds only the generated declaration glob and preserves the existing file roots. If an effective <code>exclude</code> pattern or <code>compilerOptions.outDir</code> omits those declarations, it leaves the config unchanged and reports a manual review note rather than changing the project&#39;s file roots. If it cannot resolve the extended config, it also reports a manual review note.</li></ul><p>The source transform changes parsed module specifiers only; it leaves comments, examples and other string values alone. Existing custom build and typecheck commands are kept and reported for manual review. The build command is recognized only as <code>pumpkin-plugin-build &lt;entry&gt; &lt;output&gt;</code> or <code>pnpm exec pumpkin-plugin-build &lt;entry&gt; &lt;output&gt;</code>, with optional simple quotes around either path. Flags, extra arguments, command chaining, shell variable expansions and other launchers are left for manual review. The codemod does not update lockfiles or run package manager commands.</p><h2 id="review-and-finish-the-migration" tabindex="-1">Review and finish the migration <a class="header-anchor" href="#review-and-finish-the-migration" aria-label="Permalink to “Review and finish the migration”">​</a></h2><p>Review every file and note in the preview. After applying the codemod, inspect the diff:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span></span></code></pre></div><p>Then complete the project-specific steps:</p><ol><li>Run your package manager&#39;s install command to refresh the lockfile.</li><li>Check <code>pumpkinPlugin.wasi</code> and add the WASI capabilities the plugin uses. Use the <a href="/pumpkin-plugins/guides/creating-a-plugin#files-and-network-access">capability reference</a> to identify capability names and related permissions. The codemod initializes a missing list as <code>[]</code>; it cannot determine capability use from arbitrary plugin code.</li><li>Confirm <code>tsconfig.json</code> includes the generated declaration glob. When there is no effective <code>include</code>, a local or inherited <code>files</code> list stays in place and only generated declarations are added. If neither <code>include</code> nor <code>files</code> is defined, TypeScript uses its default file inclusion. Check the codemod&#39;s manual review note if <code>exclude</code> or <code>compilerOptions.outDir</code> covers <code>build</code>.</li><li>Run the project&#39;s typecheck, build and tests.</li><li>Review the migration guide&#39;s behavior and license notes, including diagnostics, IPC rejections, callback cleanup and runtime tick validation.</li></ol><p>If the codemod reports that it cannot infer builder paths, configure <code>pumpkinPlugin.entry</code> and <code>pumpkinPlugin.output</code>, then update the build command yourself. Do not replace a custom command until you have confirmed its additional steps are preserved.</p>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};